#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> par(n);
    for (int i = 0; i < n; i++) cin >> par[i];
    long long q;
    cin >> q;
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    const int LOG = 15;
    int count = (int)n;
    vector<vector<int>> up(LOG, vector<int>(count + 1, 0));
    for (int v = 1; v <= count; v++) up[0][v] = (int)par[v - 1];
    for (int j = 1; j < LOG; j++) {
        for (int v = 1; v <= count; v++) up[j][v] = up[j - 1][up[j - 1][v]];
    }
    for (const vector<long long>& query : qs) {
        int v = (int)query[0];
        long long k = query[1];
        if (k >= count) {
            cout << -1 << "\n";
            continue;
        }
        for (int j = 0; j < LOG; j++) {
            if ((k >> j) & 1) v = up[j][v];
        }
        cout << (v == 0 ? -1 : v) << "\n";
    }

    return 0;
}

