import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] par = new long[(int) n];
        for (int i = 0; i < par.length; i++) par[i] = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int LOG = 15;
        int count = (int) n;
        int[][] up = new int[LOG][count + 1];
        for (int v = 1; v <= count; v++) up[0][v] = (int) par[v - 1];
        for (int j = 1; j < LOG; j++) {
            for (int v = 1; v <= count; v++) up[j][v] = up[j - 1][up[j - 1][v]];
        }
        StringBuilder out = new StringBuilder();
        for (long[] query : qs) {
            int v = (int) query[0];
            long k = query[1];
            if (k >= count) {
                out.append(-1).append("\n");
                continue;
            }
            for (int j = 0; j < LOG; j++) {
                if (((k >> j) & 1) != 0) v = up[j][v];
            }
            out.append(v == 0 ? -1 : v).append("\n");
        }
        System.out.print(out);
    }
}
